  ('looker-studio', 'Google Data Studio (Looker Studio)', 'Data', 'Beginner', 'Explore dashboards and business reports from approved data sources; verify connectors, sharing permissions and any associated costs.', 'Reporting', 'https://cloud.google.com/data-studio', 50)
insert into public.starter_packs (id, title, description, level, file_path, position) values
  ('ai-prompt-pack', 'Beginner AI Starter Pack', 'Helpful prompts, examples, and quick AI workflow ideas for getting started fast.', 'Beginner', 'downloads/ai-prompt-pack.md', 0),
  ('automation-kit', 'No-Code Automation Kit', 'Workflow templates and practical steps for saving time and reducing repetitive work.', 'Beginner', 'downloads/automation-kit.md', 1),
  ('website-bundle', 'Website Starter Bundle', 'A practical toolkit for building and publishing a small online project.', 'Beginner', 'downloads/website-bundle.md', 2),
  ('coding-basics-kit', 'Coding Basics Kit', 'A starter set of learning tasks, concepts, and mini-project ideas.', 'Beginner', 'downloads/coding-basics-kit.md', 3),
  ('ml-workbook', 'ML Foundations Workbook', 'A beginner-friendly workbook for ML concepts, data thinking, and small experiments.', 'Beginner', 'downloads/ml-workbook.md', 4),
  ('productivity-boost', 'AI Productivity Boost', 'Use AI to simplify writing, planning, research, and daily task management.', 'Beginner', 'downloads/productivity-boost.md', 5),
  ('design-starter-kit', 'Design Starter Kit', 'Design principles, a prototyping routine and a feedback checklist for beginners.', 'Beginner', 'downloads/design-starter-kit.md', 6),
  ('app-launch-kit', 'First App Launch Kit', 'A scoped plan for taking a small app idea to a published first version.', 'Intermediate', 'downloads/app-launch-kit.md', 7),
  ('ai-coding-prompts', 'AI Coding Prompt Pack', 'Copy-ready prompts and habits for learning and building with coding assistants.', 'Intermediate', 'downloads/ai-coding-prompts.md', 8),
  ('content-creator-kit', 'AI Content Creator Kit', 'Prompts, a simple creator loop and a responsible-creating checklist for posts, images and short videos.', 'Beginner', 'downloads/content-creator-kit.md', 9),
  ('origin-analysis-kit', 'Origin Data Analysis Kit', 'A menu cheat sheet, key formulas and AI prompt templates for analysing measurement data in Origin.', 'Intermediate', 'downloads/origin-analysis-kit.md', 10),
  ('data-visualization-kit', 'Data Visualization Starter Kit', 'A chart-selection workflow, Colab prompt and review checklist for clear, honest data visuals.', 'Beginner', 'downloads/data-visualization-kit.md', 11),
  ('research-prompt-kit', 'AI Research Prompt Kit', 'Prompts and an evidence workflow for finding, checking and synthesizing real research sources.', 'Beginner', 'downloads/research-prompt-kit.md', 12),
  ('ai-for-education-kit', 'AI for Teachers and Students Kit', 'Practical teacher and student prompts with privacy, verification and academic-integrity checklists.', 'Beginner', 'downloads/ai-for-education-kit.md', 13),
  ('ai-website-kit', 'AI Website Builder Kit', 'A website brief template, prompts for drafting and reviewing a page, and a pre-publish checklist.', 'Beginner', 'downloads/ai-website-kit.md', 14),
  ('advanced-measurement-analysis-kit', 'Advanced Measurement Analysis Kit', 'A repeatable checklist and report template for pump logs, scanner maps, mass-loading data and independent run comparisons.', 'Intermediate', 'downloads/advanced-measurement-analysis-kit.md', 15),
  ('ai-workflows-kit', 'AI Workflows and Agents Kit', 'A workflow design template, build prompt, guardrail checklist and weekly review for AI automations and simple agents.', 'Intermediate', 'downloads/ai-workflows-kit.md', 16),
  ('advanced-web-dev-kit', 'Advanced Web Development with AI Kit', 'A spec template, small-change prompt, code review checklist and pre-deploy checklist for building apps with an AI assistant.', 'Intermediate', 'downloads/advanced-web-dev-kit.md', 17),
  ('advanced-no-code-kit', 'Advanced No-Code Automation Kit', 'A process map, data checks, decision table, error plan and runbook outline for reliable no-code automations.', 'Intermediate', 'downloads/advanced-no-code-kit.md', 18),
  ('ai-small-business-kit', 'AI Small Business Kit', 'Customer research, product copy, FAQ and campaign worksheets with a fact-checking checklist.', 'Beginner', 'downloads/ai-small-business-kit.md', 19),
  ('ai-video-creation-kit', 'AI Video Creation Kit', 'A short-video brief, storyboard, asset permission log and caption review checklist.', 'Beginner', 'downloads/ai-video-creation-kit.md', 20),
  ('ai-career-skills-kit', 'AI Career Skills Kit', 'Evidence-based resume prompts, interview practice and an application tracking template.', 'Beginner', 'downloads/ai-career-skills-kit.md', 21),
  ('ai-spreadsheets-kit', 'Excel Data Cleaning & PDF-to-Excel Kit', 'Three spreadsheet service exercises with fictional data, PDF source checks, known subtotals, exceptions and private handover worksheets.', 'Beginner', 'downloads/ai-spreadsheets-kit.md', 22),
  ('ai-automation-services-kit', 'Small Business Workflow Automation Kit', 'Three practice projects: customer enquiry tracking, appointment reminders and weekly business reports, with sample data, checked results and handover worksheets.', 'Beginner', 'downloads/ai-automation-services-kit.md', 23),
  ('ai-content-services-kit', 'AI Content Services Kit', 'A fictional bakery brief, claim ledger, revision log and content-service handover worksheet.', 'Beginner', 'downloads/ai-content-services-kit.md', 24),
  ('ai-cad-services-kit', 'AI + CAD Concept Services Kit', 'Concept-only dimensions, revision checks, licensing boundaries and a traceable handover worksheet.', 'Beginner', 'downloads/ai-cad-services-kit.md', 25),
  ('micro-saas-validation-kit', 'Micro-SaaS Validation Kit', 'Problem evidence, a local prototype specification, five boundary tests and a validation decision worksheet.', 'Beginner', 'downloads/micro-saas-validation-kit.md', 26),
  ('ai-education-services-kit', 'AI Education Services Kit', 'An adult workshop brief, original lesson plan, checked rubric and accessible delivery checklist.', 'Beginner', 'downloads/ai-education-services-kit.md', 27),
  ('ai-video-business-kit', 'AI Video Creation for Business Kit', 'Three short-form video briefs, script and caption worksheets, seven evidence checks and a private service handover.', 'Beginner', 'downloads/ai-video-business-kit.md', 28),
  ('freelance-client-discovery-kit', 'Freelance Client Discovery & Project Scoping Kit', 'Neutral discovery questions, a project-fit checklist, bounded scope and proposed change worksheets for fictional practice.', 'Beginner', 'downloads/freelance-client-discovery-kit.md', 29),
  ('ai-commerce-services-kit', 'AI-Powered Commerce and Logistics Kit', 'Three fictional practice tracks for online retail, marketplace operations and logistics, with AI prompts, checked results and handover worksheets.', 'Beginner', 'downloads/ai-commerce-services-kit.md', 30),
  ('ai-privacy-fact-checking-kit', 'AI Privacy and Fact-Checking Kit', 'A redaction checklist, claim-check worksheet and safe prompts for protecting private details and verifying AI answers against real sources.', 'Beginner', 'downloads/ai-privacy-fact-checking-kit.md', 31)
insert into public.paths (id, title, level, description, badge, goal_id, steps, position) values
  ('ai-beginner', 'AI for Beginners', 'Beginner', 'Learn what AI is, how prompts work, and how to use AI in practical day-to-day ways.', 'AI', 'learn-ai', array['Learn the core idea of AI', 'Understand prompt writing', 'Use AI in real tasks', 'Build a small workflow']::text[], 0),
  ('no-code-automation', 'No-Code Automation', 'Beginner', 'Explore practical automation ideas that save time and reduce repetitive work.', 'Automation', 'automate-work', array['Understand workflows', 'Connect simple tools', 'Automate a task', 'Review results and improve']::text[], 1),
  ('web-starter', 'Website Starter', 'Beginner', 'Learn the fundamentals of web structure, publishing, and creating a simple online project.', 'Web', 'build-website', array['Learn web basics', 'Design the layout', 'Build a simple page', 'Publish and share']::text[], 2),
  ('coding-foundations', 'Coding Foundations', 'Beginner', 'Set up your environment, learn core concepts, and build tiny projects with confidence.', 'Code', 'learn-coding', array['Install VS Code and Python, and run your first program', 'Learn variables, types and printing output', 'Use conditions and loops to make decisions', 'Write functions and work with lists', 'Track your code with Git and GitHub', 'Ask an AI assistant like Copilot or Codex to explain code', 'Build and share a mini project']::text[], 3),
  ('ml-foundations', 'ML Foundations', 'Beginner', 'Understand the key ideas behind ML, data patterns, and small practical experiments.', 'ML', 'learn-ml', array['Learn the basics of ML', 'Understand data and patterns', 'Try a notebook', 'Practice with examples']::text[], 4),
  ('ai-productivity', 'AI Productivity Path', 'Beginner', 'Use AI to improve writing, planning, research, and everyday productivity tasks.', 'Productivity', 'ai-productivity', array['Identify useful tasks', 'Define a prompt system', 'Apply AI routines', 'Review and optimize']::text[], 5),
  ('design-basics', 'Design & CAD Basics', 'Beginner', 'Learn core design principles and turn an idea into a simple visual or 3D prototype.', 'Design', 'design-cad', array['Learn basic design principles', 'Sketch an idea and choose a tool', 'Build a simple prototype', 'Gather feedback and refine']::text[], 6),
  ('first-app', 'Build Your First App', 'Intermediate', 'Go from an app idea to a small working first version you can share.', 'Code', 'build-app', array['Write the problem and a tiny scope', 'Sketch the main screens', 'Set up your project with Git and GitHub', 'Build the core feature with an AI coding assistant', 'Test with unusual input and fix bugs', 'Deploy it to a free host', 'Get feedback from a friend and plan version 2']::text[], 7),
  ('no-code-builder', 'No-Code Builder', 'Beginner', 'Build a useful small system with a database and automations, without writing code.', 'Automation', 'no-code', array['Pick a simple problem to solve', 'Organize your data in a table', 'Connect an automation to it', 'Share it and improve it']::text[], 8),
  ('ai-assisted-coding', 'Code With an AI Assistant', 'Intermediate', 'Learn to pair with Copilot or Codex: write clear prompts, review output, and stay in control of your code.', 'Code', 'learn-coding', array['Pick an assistant and set it up in VS Code', 'Describe one small task with a clear prompt', 'Read and understand the generated code', 'Run it and write a simple test', 'Ask the assistant to find bugs and explain fixes', 'Refactor for clear names and small functions', 'Commit with Git and note what you learned']::text[], 9),
  ('content-creation', 'AI Content Creation Path', 'Beginner', 'Plan, draft and polish posts, images and short videos with AI helpers while staying original and honest.', 'Content', 'create-content', array['Choose an audience and a message', 'Draft with an AI assistant', 'Add visuals, voice or video', 'Polish, check facts and share']::text[], 10),
  ('origin-data-analysis', 'Data Analysis with Origin', 'Intermediate', 'Import and plot measurement data, check stability, integrate with weights, map scans and repeat the analysis with templates and AI prompts.', 'Data', 'analyze-data', array['Plan your analysis question', 'Import, label and plot data', 'Measure stability and integrate', 'Map scans, then repeat and report']::text[], 11),
  ('auto-data-analysis', 'Automated Data Analysis', 'Beginner', 'Skip the software settings: use short Python scripts in Colab and AI assistants to analyse measurement files, process many runs at once and validate the results.', 'Data', 'analyze-data', array['Choose an automation route', 'Run scripts on practice data', 'Process many files at once', 'Adapt with AI and validate']::text[], 12),
  ('data-visualization', 'Data Visualization Basics', 'Beginner', 'Choose a chart for your question, prepare a clean table, build a chart in Python and explain the result honestly.', 'Data', 'visualize-data', array['Choose a question and chart', 'Prepare a clean table', 'Create charts in Colab', 'Explain results clearly']::text[], 13),
  ('research-with-ai', 'Prompt Engineering for Research', 'Beginner', 'Turn a broad topic into a focused research question, find real sources, compare evidence and verify every citation.', 'Research', 'research-ai', array['Focus your research question', 'Find and check real sources', 'Build an evidence table', 'Synthesize and verify']::text[], 14),
  ('ai-for-education', 'AI for Teachers and Students', 'Beginner', 'Use practical AI workflows for lesson planning, tutoring and practice while keeping privacy, learning and academic integrity central.', 'Education', 'ai-education', array['Set safe use rules', 'Plan lessons or learn with a tutor', 'Create and review practice', 'Reflect and disclose AI help']::text[], 15),
  ('ai-website-builder', 'Build a Website with AI', 'Beginner', 'Plan a small website, let AI draft it, review and personalise it, then choose suitable hosting and publish it.', 'Web', 'build-website', array['Plan the site and write a brief', 'Generate a first draft with AI', 'Review, fix and make it yours', 'Publish and share']::text[], 16),
  ('advanced-measurement-analysis', 'Advanced Measurement Data Analysis', 'Intermediate', 'Build a defensible, repeatable analysis of pump logs and coating scanner data by auditing raw data, comparing independent runs and checking spatial mass-loading uniformity.', 'Advanced', 'analyze-data', array['Define a defensible analysis plan', 'Audit raw data before calculating', 'Measure pump stability by time window', 'Map coating uniformity and mass loading', 'Compare independent runs, not just readings', 'Make the analysis reproducible and report it']::text[], 17),
  ('ai-workflows-agents', 'AI Workflows and Agents', 'Intermediate', 'Design, build and safely test AI-powered workflows and simple agents, with approvals, limits and guardrails.', 'Advanced', 'ai-productivity', array['Choose a workflow or an agent', 'Design it on paper with stop rules', 'Build and test it in a no-code tool', 'Add guardrails, measure and improve']::text[], 18),
  ('advanced-web-dev-ai', 'Advanced Web Development with AI', 'Intermediate', 'Build and ship a small web app with an AI coding assistant using specs, Git, tests and code review.', 'Advanced', 'build-app', array['Write a spec and set up Git', 'Prompt in small steps', 'Test first, then review the AI''s code', 'Ship and maintain']::text[], 19),
  ('advanced-no-code-automation', 'Advanced No-Code Automation', 'Intermediate', 'Build reliable multi-step automations with clean data, branches, duplicate protection, retries, alerts and a runbook.', 'Advanced', 'automate-work', array['Map the process', 'Clean and map the data', 'Add branches, approvals and duplicate protection', 'Handle errors, monitor and document']::text[], 20),
  ('ai-small-business', 'AI for Small Business', 'Beginner', 'Create an evidence-based customer brief, product description, FAQ and one-week marketing plan.', 'Business', 'ai-small-business', array['Define an offer and research customer needs', 'Draft a truthful product description', 'Create a checked FAQ', 'Plan, review and measure a small campaign']::text[], 21),
  ('ai-video-creation', 'AI Video Creation', 'Beginner', 'Plan, create and edit a short video with clear captions, permissioned assets and honest AI disclosure.', 'Video', 'create-content', array['Write a brief and storyboard', 'Create or gather permissioned clips', 'Edit and caption the video', 'Review and publish responsibly']::text[], 22),
  ('ai-career-skills', 'AI Job Search and Career Skills', 'Beginner', 'Build a truthful resume, targeted cover letter, interview practice plan and application tracker.', 'Career', 'ai-career', array['Match a role to real evidence', 'Tailor a resume and cover letter', 'Practise interview answers', 'Track applications and choose a learning goal']::text[], 23),
  ('ai-spreadsheets', 'Excel Data Cleaning & PDF-to-Excel Services', 'Beginner', 'Practise Excel data cleaning, PDF-to-Excel source checks and business reports with fictional data, explicit exceptions and human review.', 'Data', 'analyze-data', array['Import and preserve a practice table', 'Check missing values and formulas', 'Reconcile a summary by hand', 'Chart and document the results']::text[], 24),
  ('ai-automation-services', 'AI Workflow Automation for Small Business', 'Beginner', 'Build customer enquiry tracking, appointment reminder automation or automated weekly business reports with fictional data, human review and safe retries.', 'Business', 'start-ai-business', array['Validate one customer problem', 'Define a safe, bounded pilot', 'Build and test a fictional enquiry demo', 'Calculate costs and prepare an honest offer', 'Plan handover and review the evidence']::text[], 25),
  ('ai-content-services', 'AI Content Services', 'Beginner', 'Create a fictional client content package, check claims and permissions, manage revisions and plan delivery.', 'Business', 'offer-content-services', array['Agree on a content brief', 'Draft and verify a content package', 'Manage one revision round', 'Scope, cost and deliver the service']::text[], 26),
  ('ai-cad-services', 'AI + CAD Concept Services', 'Beginner', 'Prepare a non-functional display-card concept with consistent dimensions, versioned views and clear exclusions.', 'Design', 'offer-cad-services', array['Define concept-only boundaries', 'Sketch and check dimensions', 'Model or document a paper alternative', 'Review revisions and hand over concept evidence']::text[], 27),
  ('micro-saas-validation', 'Micro-SaaS Validation', 'Beginner', 'Validate a narrow problem with a local-only formatter prototype, boundary tests and honest user evidence.', 'Business', 'validate-micro-saas', array['Gather problem evidence', 'Specify and prototype a tiny service', 'Test boundaries and cost assumptions', 'Observe use and decide before launch']::text[], 28),
  ('ai-education-services', 'AI Education Services', 'Beginner', 'Prepare an original adult workshop with source-checked materials, a practice rubric and accessible delivery.', 'Education', 'offer-education-services', array['Define an adult learning objective', 'Create original materials and a checked key', 'Rehearse and review accessibility', 'Scope the workshop and improve from evidence']::text[], 29),
  ('ai-video-business', 'AI Video Creation for Business', 'Beginner', 'Learn to create short-form videos with AI support: plan three business videos, write scripts, edit captions and review a private practice package.', 'Business', 'create-business-videos', array['Plan short-form business videos', 'Write AI-assisted video scripts and storyboards', 'Edit videos and check captions', 'Review permissions, revisions and handover']::text[], 30),
  ('freelance-client-discovery', 'Freelance Client Discovery & Project Scoping', 'Beginner', 'Practise client discovery questions, project-fit checks, bounded scope and proposed changes before preparing a service proposal.', 'Business', 'scope-freelance-project', array['Separate client facts from assumptions', 'Define deliverables and acceptance checks', 'Review skills, permissions and project fit', 'Propose controlled scope changes']::text[], 31),
  ('ai-online-retail', 'AI-Powered Online Retail', 'Beginner', 'Explore online retail with AI-assisted product drafts, checked costs, inventory planning and customer support using fictional data.', 'Business', 'build-ai-commerce', array['Define a retail model and validate customer needs', 'Compare fulfillment and check contribution', 'Draft factual product copy with AI', 'Check inventory and customer reports', 'Prepare a reviewed retail-support handover']::text[], 32),
  ('ai-marketplace-model', 'AI-Powered Marketplace Business Model', 'Beginner', 'Prototype a multi-vendor marketplace with seller checklists, AI-assisted catalog review, commission reconciliation and human-moderated support.', 'Business', 'build-ai-commerce', array['Define operator, seller and buyer responsibilities', 'Plan seller onboarding and platform checks', 'Review catalog facts and matching', 'Reconcile orders, refunds and commission', 'Prepare moderated support and prototype handover']::text[], 33),
  ('ai-logistics-services', 'AI-Powered Logistics Services', 'Beginner', 'Practise receiving, inventory reservations, dispatch and returns records, and AI-assisted exception reports without live shipments.', 'Business', 'build-ai-commerce', array['Define logistics scope and custody', 'Reconcile receiving and usable stock', 'Simulate picking and stock reservations', 'Review dispatch evidence and returns', 'Check service costs and handover']::text[], 34),
  ('ai-privacy-fact-checking', 'AI Privacy and Fact-Checking', 'Beginner', 'Keep private details out of AI prompts and check every AI claim against real sources before you share or rely on it.', 'Research', 'research-ai', array['Spot and redact private details before prompting', 'Split AI answers into checkable claims', 'Check each claim against a real source', 'Correct claims and record an honest review']::text[], 35)
insert into public.recommendations (goal_id, title, summary, steps) values
  ('build-ai-commerce', 'AI-Powered Commerce and Logistics', 'Choose online retail, a multi-vendor marketplace or logistics services. Practise with fictional data, checked calculations and human review before considering a live business.', array['Choose a model and gather actual customer evidence', 'Check platform, access and responsibility requirements', 'Practise AI-assisted drafts and deterministic calculations', 'Review exceptions, costs and human approval', 'Deliver a labelled prototype before planning live operations']::text[]),
  ('scope-freelance-project', 'Freelance Client Discovery & Project Scoping', 'Ask neutral questions, check evidence and define a bounded scope before drafting an offer. Practice does not approve real work.', array['Separate client facts from assumptions', 'Define deliverables and acceptance checks', 'Review skills, permissions and project fit', 'Propose controlled scope changes']::text[]),
  ('offer-content-services', 'AI Content Services', 'Create a fictional client content package, check claims and permissions, manage revisions and plan delivery.', array['Agree on a content brief', 'Draft and verify a content package', 'Manage one revision round', 'Scope, cost and deliver the service']::text[]),
  ('offer-cad-services', 'AI + CAD Concept Services', 'Prepare a non-functional display-card concept with consistent dimensions, versioned views and clear exclusions.', array['Define concept-only boundaries', 'Sketch and check dimensions', 'Model or document a paper alternative', 'Review revisions and hand over concept evidence']::text[]),
  ('validate-micro-saas', 'Micro-SaaS Validation', 'Validate a narrow problem with a local-only formatter prototype, boundary tests and honest user evidence.', array['Gather problem evidence', 'Specify and prototype a tiny service', 'Test boundaries and cost assumptions', 'Observe use and decide before launch']::text[]),
  ('offer-education-services', 'AI Education Services', 'Prepare an original adult workshop with source-checked materials, a practice rubric and accessible delivery.', array['Define an adult learning objective', 'Create original materials and a checked key', 'Rehearse and review accessibility', 'Scope the workshop and improve from evidence']::text[]),
  ('start-ai-business', 'AI Workflow Automation for Small Business', 'Practise customer enquiry tracking, appointment reminder automation or automated weekly business reports. Validate demand and inspect fictional results before connecting real accounts.', array['Validate one customer problem', 'Define a safe, bounded pilot', 'Build and test a fictional enquiry demo', 'Calculate costs and prepare an honest offer', 'Plan handover and review the evidence']::text[]),
  ('learn-ai', 'AI for Beginners', 'Start with AI basics, prompt writing, and simple real-world workflows before moving into deeper tool usage.', array['Understand AI basics', 'Learn prompt writing', 'Use AI in daily tasks', 'Build a small practical project']::text[]),
  ('build-website', 'Website Builder Path', 'Learn the essential steps for designing, creating, and publishing a simple website without feeling lost.', array['Learn structure and design', 'Create a simple layout', 'Publish your first page', 'Refine and share']::text[]),
  ('automate-work', 'Automation Starter', 'Use beginner-friendly tools to reduce repetitive tasks and improve the way you work.', array['Identify a repetitive task', 'Choose a workflow tool', 'Connect two or three tools', 'Test and adjust']::text[]),
  ('learn-coding', 'Coding Foundations', 'Learn the basics of coding and use small projects to build confidence before deeper learning.', array['Set up your workspace', 'Learn basic logic', 'Build a simple script', 'Use AI to explain and review your code', 'Practice with mini projects']::text[]),
  ('learn-ml', 'Machine Learning Foundations', 'Understand the big ideas behind ML, data patterns, and beginner-friendly experiments.', array['Learn key ML concepts', 'Work with data', 'Try a notebook', 'Practice and review']::text[]),
  ('design-cad', 'Design and CAD Path', 'Use design thinking and simple CAD tools to build creative ideas and prototypes with confidence.', array['Learn design basics', 'Explore a tool', 'Create simple concepts', 'Refine and share']::text[]),
  ('build-app', 'App Building Path', 'Start with simple app ideas, product thinking, and the tools that help you build a first version.', array['Define the idea and tiny scope', 'Sketch the user flow', 'Build a prototype with an AI coding assistant', 'Test with real people', 'Publish and improve']::text[]),
  ('no-code', 'No-Code Starter', 'Use easy tools to build workflows and small systems without needing to write code.', array['Choose a simple problem', 'Map the flow', 'Build the workflow', 'Review and improve']::text[]),
  ('ai-productivity', 'AI Productivity Path', 'Learn how AI can support writing, planning, research, and daily work in a practical way.', array['Identify daily repetitive tasks', 'Create reusable prompts', 'Apply AI to real work', 'Review and improve results']::text[]),
  ('create-content', 'Content Creation Path', 'Plan an idea, draft it with AI, add visuals or voice, then polish it in your own voice before you share.', array['Pick one audience and message', 'Draft with an AI assistant', 'Add images, voice or video', 'Edit, check facts and publish']::text[]),
  ('analyze-data', 'Data Analysis Path', 'Learn to import, plot, measure and report on measurement data such as pump logs and scanner maps. Use Origin for graphs, or automate the analysis with Python scripts and AI assistants.', array['Write your analysis question', 'Import, label and plot data', 'Measure stability, integrate and fit', 'Map scans, then template and report']::text[]),
  ('visualize-data', 'Data Visualization Path', 'Use clear charts to answer questions about data. Start with clean tables, choose a chart, create it in Python or Colab and explain its limits.', array['Choose a question and chart', 'Prepare and label data', 'Create and review visualizations', 'Explain the evidence and limitations']::text[]),
  ('research-ai', 'Research Prompting Path', 'Use AI to narrow research questions, organize evidence and draft synthesis, while verifying original sources and every citation yourself.', array['Focus a research question', 'Find real sources', 'Compare evidence and limitations', 'Verify and cite the final brief']::text[]),
  ('ai-education', 'AI for Teachers and Students Path', 'Use AI for lesson planning, tutoring and practice without sharing personal student data or handing over human judgement and learning.', array['Set privacy and course rules', 'Plan a lesson or study with a tutor', 'Create and review practice', 'Reflect on and disclose AI use']::text[]),
  ('ai-small-business', 'Small Business Content Path', 'Start with real customer evidence, draft useful content and check every claim before sharing.', array['Define an offer and research customer needs', 'Draft a truthful product description', 'Create a checked FAQ', 'Plan, review and measure a small campaign']::text[]),
  ('create-business-videos', 'Create Short-Form Videos with AI for Business', 'Plan three fictional business videos, write scripts and captions, check finished exports and prepare an honest service offer. AI generation is optional; no views, sales or client approval are promised.', array['Plan short-form business videos', 'Write AI-assisted video scripts and storyboards', 'Edit videos and check captions', 'Review permissions, revisions and handover']::text[]),
  ('ai-career', 'Career Skills Path', 'Use real experience to prepare applications and interview practice, then plan a manageable skill-building project.', array['Match a role to real evidence', 'Tailor a resume and cover letter', 'Practise interview answers', 'Track applications and choose a learning goal']::text[])
